-- Aprovação das questões revisadas em 08/10/2026 (423: 96 da trilha e 327 do banco).
-- Não é migração: roda uma vez, à mão, no SQL Editor do Supabase, depois da
-- 0013 (texto do banco sincronizado) e da 0014 (tabelas da revisão).
-- Revisão feita pelo Claude, a pedido do dono, questão por questão (gabarito,
-- alternativas, explicação e base legal); fica registrada em
-- v2.question_reviews como 'aprovar', com a versão do texto revisado.
-- Seguro rodar de novo:
-- - banco: só libera ('ativa') a questão que ainda está em 'revisao' E com o
--   mesmo texto que foi revisado; se o texto mudou, ela fica na fila;
-- - trilha: só grava se ainda não há aprovação desta versão. Se o texto da
--   trilha mudar depois, a versão nova volta sozinha para a fila.
BEGIN;

CREATE TEMP TABLE aprovacao (
  id text PRIMARY KEY, versao text NOT NULL, origem text NOT NULL,
  enunciado text NOT NULL, alternativas jsonb NOT NULL, correta int NOT NULL, explicacao text NOT NULL
) ON COMMIT DROP;


WITH liberadas AS (
  UPDATE v2.questions q SET status = 'ativa', updated_at = now()
  FROM aprovacao a
  WHERE a.origem = 'banco' AND q.id = a.id AND q.status = 'revisao'
    AND q.enunciado = a.enunciado AND q.alternativas = a.alternativas
    AND q.correta = a.correta AND q.explicacao = a.explicacao
  RETURNING q.id
)
SELECT a.id, a.versao, 'aprovar', 'Revisão do Claude a pedido do dono (08/10/2026).', 'revisao-claude', 'claude (a pedido do dono)'
FROM aprovacao a
WHERE a.id IN (SELECT id FROM liberadas)
   OR (a.origem = 'trilha' AND NOT EXISTS (
        SELECT 1 FROM v2.question_reviews r
        WHERE r.question_id = a.id AND r.versao = a.versao AND r.acao = 'aprovar'));

-- Conferência: o que ficou de fora (deve vir vazio).
SELECT a.id, q.status, 'texto diferente do revisado (rode a 0013 antes)' AS motivo
FROM aprovacao a JOIN v2.questions q ON q.id = a.id
WHERE a.origem = 'banco' AND q.status = 'revisao'
UNION ALL
SELECT a.id, null, 'questão não está em v2.questions (rode a 0007 e a 0008)'
FROM aprovacao a
WHERE a.origem = 'banco' AND NOT EXISTS (SELECT 1 FROM v2.questions q WHERE q.id = a.id);

COMMIT;
